WITH lines AS (SELECT id, host, level, latency_ms, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS attr_key, value), cleaned AS (SELECT *, SUBSTRING(host, 1, 4) AS host_prefix FROM lines WHERE attr_key = 'version'), enriched AS (SELECT *, ROW_NUMBER() OVER (ORDER BY latency_ms, id, attr_key) AS event_seq, MIN(latency_ms) OVER (PARTITION BY attr_key) AS attr_key_min_latency_ms FROM cleaned WHERE level = 'INFO'), metrics AS (SELECT *, NTILE(5) OVER (PARTITION BY level ORDER BY event_seq, id, attr_key) AS event_seq_bucket, FIRST_VALUE(latency_ms, TRUE) OVER (PARTITION BY attr_key ORDER BY latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latency_ms, LAST_VALUE(latency_ms) IGNORE NULLS OVER (PARTITION BY host ORDER BY attr_key_min_latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_latency_ms FROM enriched), scored AS (SELECT *, LEAD(event_seq, 1) OVER w_grp AS next_event_seq, DENSE_RANK() OVER (ORDER BY event_seq_bucket) AS event_seq_bucket_dense_rank, LAG(attr_key_min_latency_ms, 1) OVER (PARTITION BY level ORDER BY first_known_latency_ms, id, attr_key) AS prev_attr_key_min_latency_ms FROM metrics WINDOW w_grp AS (PARTITION BY attr_key ORDER BY event_seq, id, attr_key)), metrics_app_logs AS (SELECT *, SUM(event_seq_bucket) OVER (PARTITION BY level ORDER BY latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_event_seq_bucket, AVG(event_seq_bucket) OVER (PARTITION BY level ORDER BY latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_event_seq_bucket, MAX(event_seq_bucket) OVER (PARTITION BY level ORDER BY latency_ms, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_event_seq_bucket FROM scored), with_windows AS (SELECT *, LAST_VALUE(first_known_latency_ms, TRUE) OVER (PARTITION BY level ORDER BY running_max_event_seq_bucket, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_first_known_latency_ms, SUM(attr_key_min_latency_ms) OVER (PARTITION BY level) AS level_sum_attr_key_min_latency_ms, FIRST_VALUE(attr_key) IGNORE NULLS OVER (ORDER BY running_avg_event_seq_bucket, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_attr_key FROM metrics_app_logs), grouped AS (SELECT CASE WHEN running_avg_event_seq_bucket >= 7.6 THEN 'HIGH' ELSE 'LOW' END AS running_avg_event_seq_bucket_tier, CASE WHEN running_max_event_seq_bucket >= 8.3 THEN 'HIGH' ELSE 'LOW' END AS running_max_event_seq_bucket_tier, host, SUM(latency_ms) AS total_latency_ms, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list, SIZE(COLLECT_SET(attr_key)) AS num_attr_keys, SIZE(COLLECT_SET(attr_key)) AS num_attr_keys_2, GROUPING(CASE WHEN running_avg_event_seq_bucket >= 7.6 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM with_windows GROUP BY CUBE (CASE WHEN running_avg_event_seq_bucket >= 7.6 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN running_max_event_seq_bucket >= 8.3 THEN 'HIGH' ELSE 'LOW' END, host)) SELECT running_avg_event_seq_bucket_tier, host, total_latency_ms, attr_key_list, num_attr_keys, CASE WHEN host RLIKE '^(h4|h3)$' THEN 'CORE' WHEN host RLIKE '^(h1|h2)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS host_zone FROM grouped ORDER BY running_avg_event_seq_bucket_tier DESC, host DESC;
